// TH18 Extra Stage 7 Boss7 nonspell (st07bs.ecl.txt:669-728, Boss7_at 730-755).
// source==card frame map: shell buffer 120 + spawn offset, so source t maps to card ~125+t
// (first volley card 306 = source ~181); source slot-0 timeout 4200 -> card ~4325;
// card time_limit 4380 leaves the ~55-60 frame tail.

const TIME_LIMIT: int = 4380;
const OPENING_BUFFER: int = 120;

// TH18 type12 arrowhead, color14 (bullet-types.md 48-type table).
const TH18_ARROWHEAD: int = 544;
const B7_COLOR: int = 14;

// src st07bs:709 moveLimit(0,128,240,128): full 240x128 box centred at (0,128).
const B7_LIMIT_LEFT: fx = -120fx;
const B7_LIMIT_RIGHT: fx = 120fx;
const B7_LIMIT_TOP: fx = 64fx;
const B7_LIMIT_BOTTOM: fx = 192fx;
// moveRand direction inner region is centre +- width/height/4 (movement.md).
const B7_INNER_X: fx = 60fx;
const B7_INNER_TOP: fx = 96fx;
const B7_INNER_BOTTOM: fx = 160fx;

// src Boss7_at:733-744: etAim(5)->ring + half-way offset pi/5 (36deg);
// etDist(32) and ANIM a=1 birth displacement -4*initial speed are folded into
// the per-layer sh_dist below.

// src Boss7_at:739-741: ANIM(a=1) [birth stage omitted], VELTIME(60,r=3,s=keep angle),
// ANGLE_ACCEL(30,r=-0.01,s=0). Speed ramps v0->3 over 60 frames, then -0.01/frame for 30.
xformdef B7_BULLET {
    step_speed(3fx, 60);
    wait(60);
    set_accel(-0.01fx);
    wait(30);
    set_accel(0fx);
}

// Each source Boss7_at call owns one emitter slot; the two async calls differ only in
// step (D=+-9deg) and layer rotation (F=-+6deg). Source samples ANGLE_PLAYER once at
// async entry, then rotates by D every volley (no per-volley re-aim).
async sub b7_emitter(step: angle, layer: angle) {
    var base: angle = aim_player() + 36deg;
    sh_reset(0);
    sh_sprite(0, TH18_ARROWHEAD, B7_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_offset(0, 0fx, -24fx);
    sh_xform(0, B7_BULLET);
    loop {
        // Source creation order is layer q outer, way i inner; etSpeed(1.2,0) gives
        // v(q)=1.2-0.2q, layer angle q*F and etDist=32 with ANIM birth shift
        // net 32-4*v(q).  Firing one layer at a time keeps both the per-layer dist
        // and the source order, so the layer angle is applied to the base explicitly.
        for q in 0..7 {
            var v0: fx = 1.2fx - (q as fx) * 0.2fx;
            var layer_off: int = q * (layer as int);
            sh_count(0, 5, 1);
            sh_angle(0, base + (layer_off as angle), 0deg);
            sh_speed(0, v0, 0fx);
            sh_dist(0, 32fx - 4fx * v0);
            sh_fire(0);
        }
        base = base + step;
        wait(10);
    }
}

// src st07bs:730-755 helper loop state: int slot0 = next-step count, fx0/1 = unit dir.
// The target integrates movement after ECL, so arm the next source movement tick here.
sub b7_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < B7_LIMIT_LEFT { nx = B7_LIMIT_LEFT; }
    if nx > B7_LIMIT_RIGHT { nx = B7_LIMIT_RIGHT; }
    if ny < B7_LIMIT_TOP { ny = B7_LIMIT_TOP; }
    if ny > B7_LIMIT_BOTTOM { ny = B7_LIMIT_BOTTOM; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub b7_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    b7_arm_next();
}

// src Boss7_at / moveRand(60,4,1.0), adapted from movement.md to the 240x128 limit:
// signed PI-scaled angle (unwrapped BAM), split at +-60, centre +-45 with WORD%3 side
// choice, fabs by y band, then the (unreachable here) +-pi/2 guard.
sub b7_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -B7_INNER_X {
        a = r / 3;
    } else if $self_x > B7_INNER_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < B7_INNER_TOP {
        if a < 0 { a = -a; }
    } else if $self_y > B7_INNER_BOTTOM {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    b7_begin_angle(a as angle);
}

// 60 source movement ticks: each wait(1) exposes P(k), then arm P(k+1) for phase 5.
sub b7_wait_moving(frames: int) {
    for i in 0..frames {
        wait(1);
        b7_arm_next();
    }
}

// src Boss7:669-728. Handoff clears (TIMEOUT etCancel/etClear, killAllAsync,
// enmKillAll), timerReset/setInterrupt/spellEnd/boss UI and drops are shell/external;
// entry is static ABS at (0,128), REL=0, so the zero-displacement movePosTime(0,128)
// is folded into the spawn position. Source waits 120 then 60 before the first volley.
async sub b7_boss() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    wait(120);
    // moveLimit already active in source (line 709) before the first volley.
    wait(60);
    spawn b7_emitter(9deg, -6deg);
    spawn b7_emitter(-9deg, 6deg);
    loop {
        wait(100);
        b7_move_rand();
        b7_wait_moving(60);
        wait(100);
        b7_move_rand();
        b7_wait_moving(60);
    }
}

async sub b7_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 18000, 0, 0, 0, b7_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, b7_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
